create table loki.loki_locks_logs (
    locks_log_id number default on null to_number(sys_guid(), 'xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx') not null enable,
    lock_id      number not null enable,
    schema_name  varchar2(255 byte) not null enable,
    object_type  varchar2(255 byte) not null enable,
    object_name  varchar2(255 byte) not null enable,
    locked       timestamp(6) with local time zone not null enable,
    locked_by    varchar2(255 byte) not null enable,
    released     timestamp(6) with local time zone,
    released_by  varchar2(255 byte),
    locked_ts    timestamp(6) invisible generated always as ( sys_extract_utc(locked) ) virtual,
    user_id      number not null enable,
    ddl_log_id   number
);

alter table loki.loki_locks_logs
    add constraint loki_locks_logs_pk primary key ( locks_log_id )
        using index enable;


